import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { RolepermitService } from '../../../core/services/permission/rolepermit.service';

@Injectable({
  providedIn: 'root'
})
export class UserPermissionService {

  private _lastRoleId: string | null = null;

  constructor(private http: HttpClient, private rolePermit: RolepermitService) { }


  async userPermissionList(nCaseid: string): Promise<any> {

    if (!nCaseid || this.rolePermit.permissionCaseid == nCaseid) return;
    var params = new HttpParams().set('nCaseid', nCaseid);
    try {
      const res: any = await firstValueFrom(
        this.http.get(
          `${environment.cloudUrl}${environment.coreservice}/permission/permissionlist`,
          { params: params }
        )
      );
      if (res.msg == 1) {
        this.rolePermit.setUserPermissionArray(res?.jPermission);
        this.rolePermit.permissionCaseid = nCaseid;
        return res?.jPermission;

      }
      return [];
    } catch (err) {
      console.error('Error', err);
      return [];
    }
  }


  async getUserRoleId(nCaseid: string, nUserid: string): Promise<string | null> {
    if (this._lastRoleId) return this._lastRoleId;
    try {
      const params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<any[]>(
          `${environment.cloudUrl}${environment.coreservice}/team-data/assignedusers`,
          { params }
        )
      );
      console.log('[Presenter Debug] assignedusers response:', res);
      // Response format: [{ u: userId, t: teamId, r: roleId }, ...]
      if (Array.isArray(res)) {
        const entry = res.find(item => item.u === nUserid);
        console.log('[Presenter Debug] found entry for user:', entry);
        this._lastRoleId = entry?.r || null;
      }
      console.log('[Presenter Debug] extracted roleId:', this._lastRoleId);
      return this._lastRoleId;
    } catch (err) {
      console.error('[Presenter Debug] Error fetching user role', err);
      return null;
    }
  }

  async userCasePermission(nCaseid: string): Promise<any> {
    if (!nCaseid || this.rolePermit.permissionCaseid == nCaseid) return;
    var params = new HttpParams().set('nCaseid', nCaseid);
    try {
      const res: any = await firstValueFrom(
        this.http.get(
          `${environment.cloudUrl}${environment.coreservice}/permission/casepermission`,
          { params: params }
        )
      );
      this._lastRoleId = res?.nRoleid || null;
      console.log('casepermission response:', res, 'extracted nRoleid:', this._lastRoleId);
      return res;
    } catch (err) {
      console.error('Error', err);
      return [];
    }
  }
}
